import get from 'lodash/get'
import { useCallback, useMemo, useState } from 'react'
import { Row } from '../../../../../commonStyle/index.style'
import { Button, CustomText } from '../../../../../components'
import AmountTitle from '../../../../../components/AmountTitle'
import CollapsibleCard from '../../../../../components/CollapsibleCard'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { formatMoney } from '../../../../../helpers/utility'
import { ImageUrl } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import DiscountModal from '../../../Application/components/DiscountModal'
import { TransactionDetailStyle } from './index.style'

function PolicyTransactionDetailReview (props) {
  const { data = {}, onDiscountUpdate = () => {}, discount } = props
  const [showDiscountModal, setShowDiscountModal] = useState(false)
  const premiumData = useMemo(() => {
    const oldAddonPremium = get(data, 'applicationData.product.add_on_premium', 0)
    const additionalChangeAddons = get(data, 'add_on_premium', 0) - oldAddonPremium
    return [
      {
        title: LANG_STRINGS.basicPremium,
        id: 'basicPremium',
        amount: get(data, 'basic_premium', 0)
      },
      {
        title: LANG_STRINGS.additionalToPreviousPackage,
        id: 'addOnPremium',
        amount: oldAddonPremium
      },
      {
        title: LANG_STRINGS.additionalPackageChanges,
        id: 'changesAddOnPremium',
        prefix: additionalChangeAddons < 0 ? '- Rp ' : '+ Rp ',
        amount: additionalChangeAddons < 0 ? -(additionalChangeAddons) : additionalChangeAddons
      }
    ]
  }, [data])

  const adminstrationData = useMemo(() => [
    {
      title: LANG_STRINGS.stampDuty,
      id: 'stampDuty',
      amount: get(data, 'stamp_duty', 0)
    },
    // {
    //   title: LANG_STRINGS.tax,
    //   id: 'tax',
    //   amount: get(data, 'applicationData.payment_by', '') === 'AGENT' ? (data.total_tax || 0) : 0
    // },
    {
      title: LANG_STRINGS.adminFee,
      id: 'adminFee',
      amount: data.admin_fee
    }
    // {
    //   title: LANG_STRINGS.serviceFee,
    //   id: 'serviceFee',
    //   amount: get(data, 'service_fee', 0)
    // }
  ], [data])

  const handleDiscountModal = () => {
    setShowDiscountModal(true)
  }

  const handleCloseDiscountModal = () => {
    setShowDiscountModal(false)
  }

  const handleDiscountSubmit = useCallback((discount) => {
    onDiscountUpdate(discount)
    setShowDiscountModal(false)
  }, [onDiscountUpdate])

  const renderAmountTitle = useCallback(({ title, amount, id, color, prefix }) => {
    if (!amount) return null
    return (
      <AmountTitle
        key={id}
        amount={amount}
        title={title}
        color={AgentColorPallette.fontDarkerGrey}
        amountColor={color || AgentColorPallette.black}
        amountWeight={700}
        amountPrefix={prefix}
      />
    )
  }, [])

  const renderDiscount = useCallback(() => {
    let showDiscountEdit = true

    switch (get(data, 'applicationData.status', '')) {
      case 'QUOTATION':
      case 'INITIATED':
      case 'APPLICATION_COMPLETED':
      case 'PAYMENT_PENDING':
        showDiscountEdit = true; break
      default: showDiscountEdit = false
    }

    if (get(data, 'applicationData.use_pay_later', '')) {
      showDiscountEdit = false
    }

    if (showDiscountEdit || discount) {
      return (
        <>
          <Row align='center' justify='space-between' className='discount-container'>
            <Row align='center'>
              <CustomText size='13px' color={AgentColorPallette.fontDarkerGrey}>
                {LANG_STRINGS.discount}
              </CustomText>
              {
                showDiscountEdit && !!discount && (
                  <img
                    className='vertical-align-bottom'
                    onClick={handleDiscountModal}
                    width='24px' height='24px'
                    src={ImageUrl.editButtonIcon}
                    alt=''
                  />
                )
              }
            </Row>
            <CustomText
              size='13px'
              textAlign='right'
              color={AgentColorPallette.blood}
              weight={800}
            >
              {
                discount ? (`- ${formatMoney(discount)}`) : (
                  <Button
                    className='add-discount-btn'
                    handleClick={handleDiscountModal}
                  >
                    {LANG_STRINGS.add}
                  </Button>
                )
              }
            </CustomText>
          </Row>
          {
            (data.max_discount) && (
              <CustomText size='10px' className='max-discount-info'>
                {
                  (data.max_discount < discount)
                    ? LANG_STRINGS.maxDiscountIsGreaterInfo
                    : LANG_STRINGS.maxDiscountChangeInfo.replace('XXXX', formatMoney(data.max_discount))
                }
              </CustomText>
            )
          }
        </>
      )
    } else {
      return null
    }
  }, [data, discount])

  return (
    <CollapsibleCard title={LANG_STRINGS.transactionDetails} isOpen>
      <TransactionDetailStyle>
        {
          premiumData.map(item => (
            renderAmountTitle(item)
          ))
        }
        <AmountTitle
          amount={get(data, 'sub_total', 0)}
          title={LANG_STRINGS.subTotal}
          color={AgentColorPallette.fontDarkerGrey}
          amountColor={AgentColorPallette.darkCharcoal}
          amountWeight={700}
          bgColor={AgentColorPallette.fontLightGrey}
          className='sub-total-amount'
        />
        {
          adminstrationData.map(item => (
            renderAmountTitle(item)
          ))
        }
        <div className='separator' />
        {
          renderDiscount()
        }
      </TransactionDetailStyle>
      {
        showDiscountModal && (
          <DiscountModal
            showDiscountModal={showDiscountModal}
            onClose={handleCloseDiscountModal}
            commission={data.commission}
            maxDiscount={data.max_discount}
            subTotal={data.sub_total}
            comissionPercent={data.discount_percentage}
            onSubmitDiscount={handleDiscountSubmit}
          />
        )
      }
    </CollapsibleCard>
  )
}

export default PolicyTransactionDetailReview
