import { resetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import get from 'lodash/get'
import isEmpty from 'lodash/isEmpty'
import { useCallback, useEffect, useMemo, useState, useRef } from 'react'
import { BottomActionContainerStyle, Row } from '../../../../../../commonStyle/index.style'
import { Container } from '../../../../../../components'
import AmountTitle from '../../../../../../components/AmountTitle'
import ButtonWithIcon from '../../../../../../components/ButtonWithIcon'
import ConfirmationModal from '../../../../../../components/ConfirmationModal'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { TRANSACTION_EDIT_SUCCESS } from '../../../../../../constants/cookies'
import { setToLocalStorage } from '../../../../../../helpers/localstorage'
import { CHECK_GOLD } from '../../../../../../images'
import { LANG_STRINGS } from '../../../../../../lang'
import AddonsReviewList from '../../../components/AddonsReviewList'
import PolicyTransactionDetailReview from '../../../components/PolicyTransactionDetailReview'
import { mvPackageDetailBody, propertyPackageData } from '../../../constants'
import { useEditUpdateQuotation, useGetPackageDetails } from '../../../state/hooks/usePolicyState'
import { PolicyAddonReviewStyle } from './index.style'

function PolicyAddonReviewContainer (props) {
  const { location, match, history } = props

  const policyId = useMemo(() => match.params.policyId, [match])
  const pageData = useMemo(() => ({
    applicationData: (location.state.applicationDetail) || {},
    addons: (location.state.addons) || {},
    isMVProduct: location.state.isMVProduct
  }), [location.state])

  const [confirmModal, setConfirmModal] = useState({
    show: false,
    confirmText: ''
  })
  const [snackbarMap, setSnackbarMap] = useState({
    show: false,
    error: false
  })
  const [discount, setDiscount] = useState(pageData.applicationData && pageData.applicationData.discount)
  const that = useRef({})

  const [{ UPDATE_QUOTATION_ERROR, updateQuotationStatus }, dispatchError] = useErrorContextValue()
  const [{ UPDATE_QUOTATION_LOADER, GET_PACKAGE_DETAIL_LOADER }] = useLoaderContextValue()
  const [, editUpdateQuotationRequest] = useEditUpdateQuotation()
  const [{ getPackageDetailData = {} }, getPackageDetailsRequest] = useGetPackageDetails()

  const updateSnackBar = useCallback((text, error) => {
    setSnackbarMap({
      error,
      show: true,
      msg: text
    })
    setTimeout(() => {
      setSnackbarMap({
        show: false
      })
    }, 2000)
  }, [])

  useEffect(() => {
    if (GET_PACKAGE_DETAIL_LOADER === undefined) {
      let body = {}
      if (pageData.isMVProduct) {
        body = mvPackageDetailBody(pageData.applicationData, pageData.addons)
      } else {
        body = propertyPackageData(
          {
            ...(get(pageData.applicationData, 'policy_detail', {})),
            package_code: get(pageData.applicationData, 'product.package.product.code', '')
          },
          pageData.addons
        )
      }
      that.current.addonsBody = body
      getPackageDetailsRequest({
        body,
        packageCode: pageData.applicationData && pageData.applicationData.code
      })
    }
  }, [
    getPackageDetailsRequest, GET_PACKAGE_DETAIL_LOADER, pageData
  ])

  // handle the submit the review details
  // and redirect the the agent to transaction details page
  useEffect(() => {
    function resetUpdateStatus () {
      dispatchError(resetError({
        UPDATE_QUOTATION_ERROR: undefined,
        updateQuotationStatus: undefined
      }))
    }

    if (updateQuotationStatus === 'success') {
      setToLocalStorage(TRANSACTION_EDIT_SUCCESS, 'success')
      history.replace({
        pathname: `/transactions/${policyId}/details`
      })
      resetUpdateStatus()
    } else if (UPDATE_QUOTATION_ERROR && updateQuotationStatus) {
      updateSnackBar(updateQuotationStatus, true)
      resetUpdateStatus()
    }
  }, [
    updateSnackBar, dispatchError, history, policyId,
    updateQuotationStatus, UPDATE_QUOTATION_ERROR
  ])

  const handleChangesConfirmation = useCallback(() => {
    // take the agent confirmation before the save changes
    setConfirmModal((confirmModal) => ({
      ...confirmModal,
      show: true,
      redirect: true,
      agreeText: LANG_STRINGS.newCancel,
      confirmText: LANG_STRINGS.doYouWantToUndoTheChanges
    }))
  }, [])

  const handleSave = useCallback(() => {
    // take the agent confirmation before the save changes
    setConfirmModal((confirmModal) => ({
      ...confirmModal,
      show: true,
      agreeText: LANG_STRINGS.yes,
      confirmText: LANG_STRINGS.areYouSureYourChangesAreCorrect
    }))
  }, [])

  const handleCloseConfirmation = useCallback(() => {
    setConfirmModal({
      show: false
    })
  }, [])

  const handleDiscountReview = useCallback((value) => {
    setDiscount(value)
  }, [])

  const handleConfirmationAgree = useCallback(() => {
    // handle confirmation modal
    if (confirmModal.redirect) {
      history.replace({
        pathname: `/transactions/${policyId}/details`
      })
      return
    }
    let body = {
      discount: parseInt(discount, 10),
      edit_premium_data: true,
      customer_data: get(pageData.applicationData, 'customer_data', {}),
      ...(that.current.addonsBody)
    }
    if (pageData.isMVProduct) {
      body = {
        ...body,
        code: get(pageData.applicationData, 'product.code', ''),
        vehicle_sum_insured: get(pageData.applicationData, 'policy_detail.vehicle_sum_insured', ''),
        basic_premium: get(pageData.applicationData, 'product.basic_premium', '')
      }
    } else {
      body = {
        ...body,
        code: get(pageData.applicationData, 'product.code', ''),
        basic_premium: get(pageData.applicationData, 'product.basic_premium', ''),
        building_value: get(pageData.applicationData, 'policy_detail.building_value', ''),
        building_content_value: get(pageData.applicationData, 'policy_detail.building_content_value', ''),
        machine_value: get(pageData.applicationData, 'policy_detail.machine_value', ''),
        stock_value: get(pageData.applicationData, 'policy_detail.stock_value', ''),
        sum_insured: get(pageData.applicationData, 'policy_detail.sum_insured', ''),
        occupation_code: get(pageData.applicationData, 'policy_detail.occupation_code', ''),
        construction_class: get(pageData.applicationData, 'policy_detail.construction_class', '')
      }
    }
    editUpdateQuotationRequest({
      policyId,
      body
    })
    setConfirmModal({
      show: false
    })
  }, [
    policyId, editUpdateQuotationRequest, history,
    pageData, discount, confirmModal
  ])

  return (
    <Container
      title={LANG_STRINGS.editAddonsData}
      hideBottomTabs
      showSideMenuIcon
      sideMenuItems={[
        {
          head: LANG_STRINGS.cancel,
          handleClick: handleChangesConfirmation
        }
      ]}
      loader={UPDATE_QUOTATION_LOADER || GET_PACKAGE_DETAIL_LOADER}
    >
      <PolicyAddonReviewStyle>
        {
          !isEmpty(pageData.addons) && (
            <AddonsReviewList addons={getPackageDetailData.add_ons_cat} />
          )
        }
        <PolicyTransactionDetailReview
          data={{
            ...getPackageDetailData,
            applicationData: pageData.applicationData
          }}
          discount={discount}
          onDiscountUpdate={handleDiscountReview}
        />
        <BottomActionContainerStyle padding='0' direction='column' align='stretch'>
          <AmountTitle
            title={LANG_STRINGS.totalBill}
            titleWeight={700}
            color={AgentColorPallette.white}
            bgColor={AgentColorPallette.blood}
            className='total-bill-section'
            amount={getPackageDetailData.total_bill - discount}
          />
          <Row className='bottom-btn'>
            <ButtonWithIcon
              text={LANG_STRINGS.saveChanges}
              icon={CHECK_GOLD}
              iconRight
              onClick={handleSave}
              disabled={getPackageDetailData.max_discount < discount}
            />
          </Row>
        </BottomActionContainerStyle>
      </PolicyAddonReviewStyle>
      {
        confirmModal.show && (
          <ConfirmationModal
            showModal={confirmModal.show}
            onClose={handleCloseConfirmation}
            agreeText={confirmModal.agreeText}
            cancelText={LANG_STRINGS.no}
            confirmText={confirmModal.confirmText}
            modelTitle={LANG_STRINGS.information}
            onAgree={handleConfirmationAgree}
          />
        )
      }
      {
        snackbarMap.show && (
          <ShowSnackbar
            show={snackbarMap.show}
            text={snackbarMap.msg}
            error={snackbarMap.error}
          />
        )
      }
    </Container>
  )
}

export default PolicyAddonReviewContainer
