import isEmpty from 'lodash/isEmpty'
import { useCallback } from 'react'
import { CustomText } from '../../../../../components'
import AmountTitle from '../../../../../components/AmountTitle'
import CollapsibleCard from '../../../../../components/CollapsibleCard'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { AddonsReviewListStyle } from './index.style'

function AddonsReviewList (props) {
  const { addons = {} } = props

  const renderAddonsList = useCallback(() => {
    const mapTemplates = []
    let totalPremium = 0
    for (const categoryKey in addons) {
      const categoryAddons = addons[categoryKey]
      if (isEmpty(categoryAddons)) continue
      mapTemplates.push(
        <CustomText
          color={AgentColorPallette.black}
          weight={700}
          bottom='8px'
        >
          {categoryAddons.category_name}
        </CustomText>
      )
      for (const addon of categoryAddons.add_on) {
        const addonPremium = (addon.premium * (addon.no_passanger || 1))
        totalPremium += (addonPremium || 0)
        mapTemplates.push(
          <AmountTitle
            amount={addonPremium}
            size='12px'
            title={
              <>
                &bull;&nbsp;&nbsp;{addon.add_on_name}
              </>
            }
            color={AgentColorPallette.fontDarkerGrey}
            amountColor={AgentColorPallette.black}
            amountWeight={700}
          />
        )
      }
    }

    mapTemplates.push(
      <AmountTitle
        amount={totalPremium}
        title={LANG_STRINGS.subTotal}
        color={AgentColorPallette.fontDarkerGrey}
        amountColor={AgentColorPallette.darkCharcoal}
        amountWeight={700}
        bgColor={AgentColorPallette.fontLightGrey}
        className='sub-total-addons'
      />
    )
    return mapTemplates
  }, [addons])

  return (
    <CollapsibleCard title={LANG_STRINGS.additionalPackage} isOpen>
      <AddonsReviewListStyle>
        {
          renderAddonsList()
        }
      </AddonsReviewListStyle>
    </CollapsibleCard>
  )
}

export default AddonsReviewList
